ENUM VehicleType { BIKE, CAR, TRUCK }
ENUM SpotSize { SMALL, MEDIUM, LARGE }

CLASS Vehicle {
    number
    type

    CONSTRUCTOR(number, type) {
        this.number = number
        this.type = type
    }
}

CLASS Spot {
    id
    floor
    size
    vehicle = NULL

    CONSTRUCTOR(id, floor, size) {
        this.id = id
        this.floor = floor
        this.size = size
    }

    isAvailable() {
        RETURN vehicle == NULL
    }

    canFit(v) {
        IF v.type == BIKE
            RETURN size IN {SMALL, MEDIUM, LARGE}
        IF v.type == CAR
            RETURN size IN {MEDIUM, LARGE}
        IF v.type == TRUCK
            RETURN size == LARGE
    }
}

CLASS Ticket {
    id
    vehicle
    spot
    entryTime
    exitTime = NULL

    CONSTRUCTOR(id, vehicle, spot) {
        this.id = id
        this.vehicle = vehicle
        this.spot = spot
        entryTime = CURRENT_TIME
    }
}

CLASS ParkingFloor {
    number
    spots = LIST()

    addSpot(spot) {
        spots.add(spot)
    }

    findSpot(vehicle) {
        FOR EACH spot IN spots {
            IF spot.isAvailable() AND spot.canFit(vehicle)
                RETURN spot
        }
        RETURN NULL
    }

    availableCount() {
        count = 0
        FOR EACH spot IN spots
            IF spot.isAvailable()
                count++
        RETURN count
    }
}

CLASS ParkingLot {
    floors = LIST()
    activeTickets = MAP()
    nextTicketId = 1

    addFloor(floor) {
        floors.add(floor)
    }

    park(vehicle) {
        spot = findBestSpot(vehicle)

        IF spot == NULL
            RETURN "PARKING_FULL"

        spot.vehicle = vehicle

        ticket = new Ticket(
            nextTicketId++,
            vehicle,
            spot
        )

        activeTickets[ticket.id] = ticket
        RETURN ticket
    }

    findBestSpot(vehicle) {
        // Prefer the smallest suitable spot
        FOR EACH floor IN floors {
            spot = floor.findSpot(vehicle)
            IF spot != NULL
                RETURN spot
        }
        RETURN NULL
    }

    exit(ticketId) {
        IF NOT activeTickets.contains(ticketId)
            RETURN "INVALID_TICKET"

        ticket = activeTickets[ticketId]
        ticket.exitTime = CURRENT_TIME

        duration = ticket.exitTime - ticket.entryTime
        fee = calculateFee(ticket.vehicle.type, duration)

        ticket.spot.vehicle = NULL
        activeTickets.remove(ticketId)

        RETURN fee
    }

    calculateFee(type, duration) {
        hours = CEIL(duration / 1 HOUR)

        IF type == BIKE
            RETURN hours * 20

        IF type == CAR
            RETURN hours * 40

        IF type == TRUCK
            RETURN hours * 80
    }

    getAvailableSpots() {
        total = 0
        FOR EACH floor IN floors
            total += floor.availableCount()
        RETURN total
    }
}


