enum VehicleType { CAR, BIKE, TRUCK }
enum SpotSize { SMALL, MEDIUM, LARGE }

abstract class Vehicle {
    private String licensePlate;
    private VehicleType type;

    public abstract SpotSize getRequiredSpotSize();
}

class Car extends Vehicle {
    public SpotSize getRequiredSpotSize() { return SpotSize.MEDIUM; }
}

class Bike extends Vehicle {
    public SpotSize getRequiredSpotSize() { return SpotSize.SMALL; }
}

class Truck extends Vehicle {
    public SpotSize getRequiredSpotSize() { return SpotSize.LARGE; }
}

class Spot {
    private String spotId;
    private SpotSize size;
    private int floorNumber;
    private boolean isOccupied;

    public boolean canFitVehicle(Vehicle vehicle) {
        return !isOccupied && this.size == vehicle.getRequiredSpotSize();
    }

    public void occupy() { isOccupied = true; }
    public void vacate() { isOccupied = false; }
}

class Floor {
    private int floorNumber;
    private List<Spot> spots;

    // real-time tracking of occupancy
    public int getAvailableSpotCount(SpotSize size) {
        // count spots where isOccupied == false and size matches
    }

    public Spot findAvailableSpot(Vehicle vehicle) {
        for (Spot spot : spots) {
            if (spot.canFitVehicle(vehicle)) {
                return spot;
            }
        }
        return null; // no spot found on this floor
    }
}

class Ticket {
    private String ticketId;
    private Vehicle vehicle;
    private Spot assignedSpot;
    private LocalDateTime entryTime;
    private LocalDateTime exitTime;

    public Ticket(Vehicle vehicle, Spot spot) {
        this.vehicle = vehicle;
        this.assignedSpot = spot;
        this.entryTime = LocalDateTime.now();
    }
}

interface FeeCalculator {
    double calculateFee(Ticket ticket);
}

class HourlyFeeCalculator implements FeeCalculator {
    private Map<VehicleType, Double> ratePerHour;

    public double calculateFee(Ticket ticket) {
        Duration duration = Duration.between(ticket.entryTime, ticket.exitTime);
        double hours = Math.ceil(duration.toMinutes() / 60.0);
        double rate = ratePerHour.get(ticket.vehicle.getType());
        return hours * rate;
    }
}

class ParkingFullException extends Exception {
    public ParkingFullException(String message) {
        super(message);
    }
}

class ParkingLot {
    private List<Floor> floors;
    private FeeCalculator feeCalculator;
    private Map<String, Ticket> activeTickets; // ticketId -> Ticket

    public Ticket parkVehicle(Vehicle vehicle) throws ParkingFullException {
        Spot foundSpot = null;

        // search across all floors for an available spot
        for (Floor floor : floors) {
            Spot spot = floor.findAvailableSpot(vehicle);
            if (spot != null) {
                foundSpot = spot;
                break;
            }
        }

        // edge case: no spot available anywhere
        if (foundSpot == null) {
            throw new ParkingFullException(
                "No available spot for vehicle type: " + vehicle.getType()
            );
        }

        foundSpot.occupy();
        Ticket ticket = new Ticket(vehicle, foundSpot);
        activeTickets.put(ticket.ticketId, ticket);
        return ticket;
    }

    public double exitVehicle(String ticketId) throws Exception {
        Ticket ticket = activeTickets.get(ticketId);

        if (ticket == null) {
            throw new Exception("Invalid ticket");
        }

        ticket.exitTime = LocalDateTime.now();
        double fee = feeCalculator.calculateFee(ticket);

        ticket.assignedSpot.vacate();
        activeTickets.remove(ticketId);

        return fee;
    }

    public Map<SpotSize, Integer> getAvailabilitySummary() {
        // aggregate available spot counts per size across all floors
        // used for real-time occupancy tracking / dashboard
    }
}
